<div class="form-grid"><label class="span-2">Nombre del cargo<input name="title" value="<?php echo e(old('title',$job->title ?? '')); ?>" required></label><label>Ubicación<input name="location" value="<?php echo e(old('location',$job->location ?? '')); ?>" required placeholder="Ej. Cali, Colombia"></label><label>Modalidad<select name="modality" required><?php $__currentLoopData = ['Presencial','Remoto','Híbrido']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(old('modality',$job->modality ?? '')===$v): echo 'selected'; endif; ?>><?php echo e($v); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Tipo de contrato<select name="type" required><?php $__currentLoopData = ['Tiempo completo','Medio tiempo','Práctica','Freelance']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(old('type',$job->type ?? '')===$v): echo 'selected'; endif; ?>><?php echo e($v); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Salario / apoyo económico<input name="salary" value="<?php echo e(old('salary',$job->salary ?? '')); ?>" placeholder="Ej. A convenir"></label><label>Fecha límite de postulación<input type="date" name="expires_at" value="<?php echo e(old('expires_at',isset($job) ? optional($job->expires_at)->format('Y-m-d') : '')); ?>"></label><label class="span-2">Descripción<textarea name="description" rows="5" required><?php echo e(old('description',$job->description ?? '')); ?></textarea></label><label class="span-2">Requisitos<textarea name="requirements" rows="4"><?php echo e(old('requirements',$job->requirements ?? '')); ?></textarea></label></div>
